public class ContactTriggerHandler {
    public void handleBefore(List<Contact> newContacts, Map<Id, Contact> oldContacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        Map<Id, Account> accountsMap = new Map<Id, Account>([SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]);

        for (Contact c : newContacts) {
            if (c.AccountId != null && accountsMap.containsKey(c.AccountId)) {
                Account a = accountsMap.get(c.AccountId);
                if (String.isBlank(c.MailingCountry)) {
                    c.MailingCountry = a.BillingCountry;
                }
                if (isInsert && String.isBlank(c.LeadSource)) {
                    c.LeadSource = a.AccountSource;
                }
            }
        }
    }

    public void handleAfter(List<Contact> newContacts) {
        Set<Id> accountIdsWithPhone = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIdsWithPhone.add(c.AccountId);
            }
        }

        Map<Id, Account> accountsToUpdateMap = new Map<Id, Account>([SELECT Id, Phone FROM Account WHERE Id IN :accountIdsWithPhone AND Phone = null]);

        Set<Id> accountsUpdated = new Set<Id>();
        List<Account> accountsToDml = new List<Account>();

        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                Id accId = c.AccountId;
                if (accountsToUpdateMap.containsKey(accId) && !accountsUpdated.contains(accId)) {
                    Account acc = accountsToUpdateMap.get(accId);
                    acc.Phone = c.Phone;
                    accountsToDml.add(acc);
                    accountsUpdated.add(accId);
                }
            }
        }

        if (!accountsToDml.isEmpty()) {
            update accountsToDml;
        }
    }
}
