public class RecordSearchService {
    public static exception SearchException {}

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        // Validate maxRows
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200');
        }

        // Validate fields list
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields cannot be null or empty');
        }

        // Get SObjectType for the object (case-insensitive)
        Schema.SObjectType sObjectType = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        if (sObjectType == null) {
            throw new SearchException('Object ' + objectApiName + ' does not exist');
        }

        // Check object accessibility
        if (!sObjectType.getDescribe().isAccessible()) {
            throw new SearchException('Running user cannot read object ' + objectApiName);
        }

        Schema.DescribeSObjectResult describeResult = sObjectType.getDescribe();

        // Build a map of field API names (case-insensitive) for validation
        Map<String, String> fieldApiNames = new Map<String, String>();
        for (Schema.DescribeFieldResult fieldDescribe : describeResult.fields.getMap().values()) {
            fieldApiNames.put(fieldDescribe.getName().toLowerCase(), fieldDescribe.getName());
        }

        // Validate fields in the fields list
        List<String> selectedFields = new List<String>();
        selectedFields.add('Id'); // Always include Id
        for (String fieldName : fields) {
            String lowerCaseFieldName = fieldName.toLowerCase();
            if (!fieldApiNames.containsKey(lowerCaseFieldName)) {
                throw new SearchException('Field ' + fieldName + ' does not exist on object ' + objectApiName);
            }
            String correctFieldName = fieldApiNames.get(lowerCaseFieldName);
            // Check field accessibility
            Schema.DescribeFieldResult fieldDescribe = describeResult.fields.getMap().get(correctFieldName);
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('Running user cannot read field ' + fieldName + ' on object ' + objectApiName);
            }
            selectedFields.add(correctFieldName);
        }

        // Validate filter fields
        if (filters != null) {
            for (String filterField : filters.keySet()) {
                String lowerCaseFilterField = filterField.toLowerCase();
                if (!fieldApiNames.containsKey(lowerCaseFilterField)) {
                    throw new SearchException('Filter field ' + filterField + ' does not exist on object ' + objectApiName);
                }
                String correctFilterField = fieldApiNames.get(lowerCaseFilterField);
                Schema.DescribeFieldResult fieldDescribe = describeResult.fields.getMap().get(correctFilterField);
                // Check field accessibility
                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException('Running user cannot read filter field ' + filterField + ' on object ' + objectApiName);
                }
                // Check if field is filterable
                if (!fieldDescribe.isFilterable()) {
                    throw new SearchException('Filter field ' + filterField + ' cannot be filtered on object ' + objectApiName);
                }
            }
        }

        // Validate orderByField
        String orderByCorrectField = null;
        if (orderByField != null && !orderByField.trim().isEmpty()) {
            String lowerCaseOrderByField = orderByField.toLowerCase();
            if (!fieldApiNames.containsKey(lowerCaseOrderByField)) {
                throw new SearchException('Order-by field ' + orderByField + ' does not exist on object ' + objectApiName);
            }
            orderByCorrectField = fieldApiNames.get(lowerCaseOrderByField);
            Schema.DescribeFieldResult fieldDescribe = describeResult.fields.getMap().get(orderByCorrectField);
            // Check field accessibility
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('Running user cannot read order-by field ' + orderByField + ' on object ' + objectApiName);
            }
            // Check if field is sortable
            if (!fieldDescribe.isSortable()) {
                throw new SearchException('Order-by field ' + orderByField + ' cannot be sorted on object ' + objectApiName);
            }
        }

        // Build SOQL query
        String selectClause = 'SELECT ' + String.join(selectedFields, ', ');
        String fromClause = 'FROM ' + describeResult.getName();
        String whereClause = '';
        if (filters != null && !filters.isEmpty()) {
            List<String> conditions = new List<String>();
            for (String filterField : filters.keySet()) {
                String lowerCaseFilterField = filterField.toLowerCase();
                String correctFilterField = fieldApiNames.get(lowerCaseFilterField);
                Object filterValue = filters.get(filterField);
                String condition = correctFilterField + ' = ' + escapeValue(filterValue);
                conditions.add(condition);
            }
            whereClause = 'WHERE ' + String.join(conditions, ' AND ');
        }
        String orderByClause = '';
        if (orderByCorrectField != null) {
            orderByClause = 'ORDER BY ' + orderByCorrectField + ' ASC';
        }
        String limitClause = 'LIMIT ' + maxRows;

        String soql = selectClause + ' ' + fromClause;
        if (!whereClause.isEmpty()) {
            soql += ' ' + whereClause;
        }
        if (!orderByClause.isEmpty()) {
            soql += ' ' + orderByClause;
        }
        soql += ' ' + limitClause;

        // Execute query
        return Database.query(soql);
    }

    private static String escapeValue(Object value) {
        if (value == null) {
            return 'null';
        } else if (value instanceof String) {
            return '\'' + String.escapeSingleQuotes((String) value) + '\'';
        } else if (value instanceof Id) {
            return '\'' + (String) value + '\'';
        } else if (value instanceof Date) {
            return '\'' + ((Date) value).format('yyyy-MM-dd') + '\'';
        } else if (value instanceof Boolean) {
            return (Boolean) value ? 'true' : 'false';
        } else if (value instanceof Decimal || value instanceof Integer) {
            return String.valueOf(value);
        } else {
            // For any other type, use string representation with escaping
            return '\'' + String.escapeSingleQuotes(String.valueOf(value)) + '\'';
        }
    }
}
