public class ContactLookupAction {

    // Inner class for input parameters
    public class Request {
        @InvocableVariable(required=true)
        public String email;
    }

    // Inner class for output results
    public class Result {
        @InvocableVariable
        public Id contactId;
        @InvocableVariable
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        // Normalize emails and collect distinct non-blank emails
        Set<String> normalizedEmails = new Set<String>();
        Map<String, List<Integer>> emailToRequestIndices = new Map<String, List<Integer>>();

        for (Integer i = 0; i < requests.size(); i++) {
            Request req = requests[i];
            String normalizedEmail = normalizeEmail(req.email);

            if (normalizedEmail != null) {
                if (!emailToRequestIndices.containsKey(normalizedEmail)) {
                    emailToRequestIndices.put(normalizedEmail, new List<Integer>());
                }
                emailToRequestIndices.get(normalizedEmail).add(i);
                normalizedEmails.add(normalizedEmail);
            }
        }

        // Initialize results with default values
        for (Integer i = 0; i < requests.size(); i++) {
            Result res = new Result();
            res.found = false;
            res.contactId = null;
            results.add(res);
        }

        // If no valid emails to search, return early
        if (normalizedEmails.isEmpty()) {
            return results;
        }

        // Query all contacts (respecting running user's sharing)
        // Order by CreatedDate ASC to get earliest contacts first
        List<Contact> contacts = [SELECT Id, Email, CreatedDate FROM Contact ORDER BY CreatedDate ASC];

        // Build map of normalized email to earliest contact
        Map<String, Contact> emailToContact = new Map<String, Contact>();
        for (Contact c : contacts) {
            String normalizedEmail = normalizeEmail(c.Email);
            if (normalizedEmail != null) {
                // Since contacts are ordered by CreatedDate ASC, the first one we encounter
                // for each email is the earliest. So we only add if not already present.
                if (!emailToContact.containsKey(normalizedEmail)) {
                    emailToContact.put(normalizedEmail, c);
                }
            }
        }

        // Populate results for requests with matching contacts
        for (String normalizedEmail : emailToRequestIndices.keySet()) {
            Contact matchedContact = emailToContact.get(normalizedEmail);
            if (matchedContact != null) {
                for (Integer idx : emailToRequestIndices.get(normalizedEmail)) {
                    Result res = results[idx];
                    res.found = true;
                    res.contactId = matchedContact.Id;
                }
            }
        }

        return results;
    }

    // Helper method to normalize email (trim and lowercase)
    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim();
        if (trimmed.length() == 0) {
            return null;
        }
        return trimmed.toLowerCase();
    }
}
