public class AccountScoringJob implements Queueable {
    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    public void execute(QueueableContext context) {
        // Process up to 200 accounts from the list
        Integer batchSize = 200;
        Integer startIdx = 0;
        Integer endIdx = Math.min(batchSize, accountIds.size());

        if (accountIds.size() == 0) {
            return;
        }

        // Create a batch list manually (Apex List doesn't have subList)
        List<Id> batchAccountIds = new List<Id>();
        for (Integer i = startIdx; i < endIdx; i++) {
            batchAccountIds.add(accountIds[i]);
        }

        // Query the accounts to get AnnualRevenue
        List<Account> accounts = [SELECT Id, AnnualRevenue FROM Account WHERE Id IN :batchAccountIds];

        // Update Rating based on AnnualRevenue
        List<Account> updatedAccounts = new List<Account>();
        for (Account acc : accounts) {
            Decimal revenue = acc.AnnualRevenue;
            if (revenue == null) {
                acc.Rating = 'Cold';
            } else if (revenue >= 1000000) {
                acc.Rating = 'Hot';
            } else if (revenue >= 100000) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
            updatedAccounts.add(acc);
        }

        // Perform DML update
        update updatedAccounts;

        // If there are remaining accounts, enqueue a new job
        if (endIdx < accountIds.size()) {
            List<Id> remainingIds = new List<Id>();
            for (Integer i = endIdx; i < accountIds.size(); i++) {
                remainingIds.add(accountIds[i]);
            }
            AccountScoringJob nextJob = new AccountScoringJob(remainingIds);
            System.enqueueJob(nextJob);
        }
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        AccountScoringJob job = new AccountScoringJob(accountIds);
        return System.enqueueJob(job);
    }
}
