    public void handle(fflib_TriggerContext triggerContext) {
        Set<Id> qualifyingOpportunityIds = new Set<Id>();

        if (triggerContext.isInsert) {
            for (Opportunity opp : (List<Opportunity>)triggerContext.newRecords) {
                if (opp.StageName == 'Closed Won') {
                    qualifyingOpportunityIds.add(opp.Id);
                }
            }
        } else if (triggerContext.isUpdate) {
            for (Integer i = 0; i < triggerContext.newRecords.size(); i++) {
                Opportunity opp = (Opportunity)triggerContext.newRecords[i];
                Opportunity oldOpp = (Opportunity)triggerContext.oldRecords[i];
                if (opp.StageName == 'Closed Won' && oldOpp.StageName != 'Closed Won') {
                    qualifyingOpportunityIds.add(opp.Id);
                }
            }
        }

        if (!qualifyingOpportunityIds.isEmpty()) {
            IOpportunityFulfilmentService fulfilmentService = 
                (IOpportunityFulfilmentService)Application.Service.newInstance(IOpportunityFulfilmentService.class);
            fulfilmentService.startFulfilment(qualifyingOpportunityIds);
        }
    }
}
