public class AccountOnboardingService {
    /**
     * Creates Accounts and related Contacts based on the provided map.
     * For each account name in the map, creates an Account and Contacts for each last name.
     * All records are managed through a single fflib_SObjectUnitOfWork.
     *
     * @param contactLastNamesByAccountName Map of account names to lists of contact last names
     * @return List of newly created Account records with Ids populated
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        // Return empty list if map is null or empty
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        // Initialize the Unit of Work with the correct SObjectField types
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectField>{ Account.Id, Contact.Id }
        );

        // List to hold the newly created Accounts
        List<Account> newAccounts = new List<Account>();

        // Process each account in the map
        for (String accountName : contactLastNamesByAccountName.keySet()) {
            // Create the Account record
            Account newAccount = new Account(Name = accountName);
            uow.registerNew(newAccount);
            newAccounts.add(newAccount);

            // Create Contacts for each last name
            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames != null) {
                for (String lastName : lastNames) {
                    Contact newContact = new Contact(
                        LastName = lastName,
                        AccountId = uow.getId((SObject)newAccount)
                    );
                    uow.registerNew(newContact);
                }
            }
        }

        // Commit all work
        uow.commitWork();

        return newAccounts;
    }
}
