public class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Load opportunities
        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Filter out already Closed Won opportunities
        List<Opportunity> opportunitiesToUpdate = new List<Opportunity>();
        for (Opportunity opp : opportunities) {
            if (opp.StageName != 'Closed Won') {
                opp.StageName = 'Closed Won';
                opp.CloseDate = Date.today();
                opportunitiesToUpdate.add(opp);
            }
        }

        if (opportunitiesToUpdate.isEmpty()) {
            return 0;
        }

        // Get unit of work
        fflib_Application.UOW uow = Application.UnitOfWork.newInstance();

        // Register dirty records and events
        for (Opportunity opp : opportunitiesToUpdate) {
            uow.registerDirty(opp);
            Deal_Won__e event = new Deal_Won__e();
            event.Opportunity_Id__c = opp.Id;
            event.Amount__c = opp.Amount;
            uow.registerEvent(event);
        }

        // Commit work (this will save the opportunities and then publish the events)
        uow.commitWork();

        return opportunitiesToUpdate.size();
    }
}
