trigger CaseTrigger on Case (after update) {
    List<Id> caseIdsToProcess = new List<Id>();

    for (Case newCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(newCase.Id);

        // Check if case just closed (IsClosed changed from false to true)
        if (oldCase.IsClosed == false && newCase.IsClosed == true) {
            // Check if case has a contact
            if (newCase.ContactId != null) {
                caseIdsToProcess.add(newCase.Id);
            }
        }
    }

    // Batch the case IDs to avoid hitting the queueable limit (50 jobs per transaction)
    // Enqueue one job per batch of up to 50 cases
    for (Integer i = 0; i < caseIdsToProcess.size(); i += 50) {
        List<Id> batch = caseIdsToProcess.subList(i, Math.min(i + 50, caseIdsToProcess.size()));
        System.enqueueJob(new CaseSurveyJob(batch));
    }
}
