import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import LightningConfirm from 'lightning/confirm';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    @api opportunities;
    @track localOpportunities;

    columns = [
        { label: 'Name', fieldName: 'Name' },
        { label: 'Stage', fieldName: 'StageName' },
        { label: 'Amount', fieldName: 'Amount', type: 'currency' },
        {
            type: 'action',
            typeAttributes: {
                rowActions: [
                    { label: 'View', name: 'view' },
                    { label: 'Edit', name: 'edit' },
                    { label: 'Delete', name: 'delete' }
                ]
            }
        }
    ];

    set opportunities(value) {
        this.localOpportunities = value || [];
    }

    get opportunities() {
        return this.localOpportunities;
    }

    handleRowAction(event) {
        const action = event.detail.action;
        const row = event.detail.row;

        switch (action.name) {
            case 'view':
                this.navigateToAddOrEditRecord(row.Id, 'view');
                break;
            case 'edit':
                this.navigateToAddOrEditRecord(row.Id, 'edit');
                break;
            case 'delete':
                this.handleDelete(row.Id);
                break;
        }
    }

    navigateToAddOrEditRecord(recordId, actionName) {
        this.navigate({
            type: 'standard_record_page',
            attributes: {
                recordId: recordId,
                actionName: actionName
            }
        });
    }

    handleDelete(recordId) {
        LightningConfirm.open({
            message: 'Are you sure you want to delete this opportunity?',
            variant: 'question'
        }).then(() => {
            deleteRecord(recordId)
                .then(() => {
                    this.localOpportunities = this.localOpportunities.filter(opp => opp.Id !== recordId);
                    const toastEvent = new ShowToastEvent({
                        title: 'Opportunity deleted',
                        variant: 'success'
                    });
                    this.dispatchEvent(toastEvent);
                })
                .catch(error => {
                    const toastEvent = new ShowToastEvent({
                        title: 'Delete failed',
                        variant: 'error',
                        message: error.body.message
                    });
                    this.dispatchEvent(toastEvent);
                });
        }).catch(() => {
            // User cancelled, do nothing
        });
    }
}
