import { LightningElement, track } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    @track waiting;
    @track longestWaitMinutes;
    @track error;

    pollInterval;
    inFlight = false;
    visibilityListener;

    connectedCallback() {
        // Initial load
        this.loadStats();

        // Start polling every 60 seconds (if visible and not in flight)
        this.pollInterval = setInterval(() => {
            if (document.visibilityState === 'visible' && !this.inFlight) {
                this.loadStats();
            }
        }, 60000);

        // Listen for visibility changes
        this.visibilityListener = () => {
            if (document.visibilityState === 'visible') {
                // Load immediately when becoming visible
                this.loadStats();
            }
        };
        document.addEventListener('visibilitychange', this.visibilityListener);
    }

    disconnectedCallback() {
        // Clear polling interval
        if (this.pollInterval) {
            clearInterval(this.pollInterval);
            this.pollInterval = null;
        }

        // Remove visibility listener
        if (this.visibilityListener) {
            document.removeEventListener('visibilitychange', this.visibilityListener);
            this.visibilityListener = null;
        }

        // Reset state
        this.inFlight = false;
        this.error = null;
    }

    loadStats() {
        // Skip if a request is already in flight
        if (this.inFlight) {
            return;
        }

        this.inFlight = true;
        this.error = null;

        getQueueStats()
            .then((result) => {
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.inFlight = false;
            })
            .catch((error) => {
                this.error = error.body.message;
                this.inFlight = false;
            });
    }
}
