            .catch(error => {
                // Failure: dispatch toast event with error message
                const toastEvent = new ShowToastEvent({
                    title: 'Registration failed',
                    variant: 'error',
                    message: error.body.message
                });
                this.dispatchEvent(toastEvent);
            });
    }
