import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    @api options;

    @track activeOptionId;

    connectedCallback() {
        this.initializeOptions();
        this.updateActiveOption();
    }

    initializeOptions() {
        // Generate unique IDs for each option
        this.options.forEach((option, index) => {
            option.id = `option-${index}`;
        });
    }

    updateActiveOption() {
        if (this.value) {
            const selectedOption = this.options.find(opt => opt.value === this.value);
            if (selectedOption) {
                this.activeOptionId = selectedOption.id;
            } else {
                // If value doesn't match any option, default to first option
                this.activeOptionId = this.options.length > 0 ? this.options[0].id : '';
            }
        } else {
            // If value is empty, default to first option
            this.activeOptionId = this.options.length > 0 ? this.options[0].id : '';
        }
    }

    handleKeydown(event) {
        const key = event.key;
        const options = this.options;
        const currentIndex = options.findIndex(opt => opt.id === this.activeOptionId);

        if (key === 'ArrowDown') {
            event.preventDefault();
            const nextIndex = Math.min(currentIndex + 1, options.length - 1);
            this.activeOptionId = options[nextIndex].id;
        } else if (key === 'ArrowUp') {
            event.preventDefault();
            const prevIndex = Math.max(currentIndex - 1, 0);
            this.activeOptionId = options[prevIndex].id;
        } else if (key === 'Home') {
            event.preventDefault();
            this.activeOptionId = options[0].id;
        } else if (key === 'End') {
            event.preventDefault();
            this.activeOptionId = options[options.length - 1].id;
        } else if (key === 'Enter' || key === ' ') {
            event.preventDefault();
            const activeOption = options.find(opt => opt.id === this.activeOptionId);
            if (activeOption && activeOption.value !== this.value) {
                this.value = activeOption.value;
                this.dispatchEvent(new CustomEvent('change', { detail: { value: this.value } }));
            }
        }
        // Tab and other keys are not prevented
    }

    handleOptionClick(event) {
        const option = event.target;
        const value = option.dataset.value;
        if (value !== this.value) {
            this.value = value;
            this.activeOptionId = option.id;
            this.dispatchEvent(new CustomEvent('change', { detail: { value: this.value } }));
        } else {
            // If already selected, just update active option (no change event)
            this.activeOptionId = option.id;
        }
    }

    // Watch for changes to the value property from parent
    @track _value;
    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this.updateActiveOption();
    }
}
