public class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        // Null or empty input does nothing
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Collect all unique opportunity IDs and contact IDs
        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest request : requests) {
            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);
        }

        // Query opportunities to get primary contact and amount
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, npsp__Primary_Contact__c, Amount FROM Opportunity WHERE Id IN :opportunityIds]
        );

        // Query existing OpportunityContactRoles (OCR)
        List<OpportunityContactRole> ocrs = [SELECT Id, OpportunityId, ContactId, Role FROM OpportunityContactRole WHERE OpportunityId IN :opportunityIds AND ContactId IN :contactIds];
        Map<String, OpportunityContactRole> ocrMap = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : ocrs) {
            ocrMap.put(ocr.OpportunityId + '-' + ocr.ContactId, ocr);
        }

        // Query existing Partial Soft Credits (PSC)
        List<npsp__Partial_Soft_Credit__c> pscs = [SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c FROM npsp__Partial_Soft_Credit__c WHERE npsp__Opportunity__c IN :opportunityIds AND npsp__Contact__c IN :contactIds];
        Map<String, npsp__Partial_Soft_Credit__c> pscMap = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : pscs) {
            pscMap.put(String.valueOf(psc.npsp__Opportunity__c) + '-' + String.valueOf(psc.npsp__Contact__c), psc);
        }

        // Query contacts to get names for PSC
        Map<Id, Contact> contactMap = new Map<Id, Contact>(
            [SELECT Id, Name FROM Contact WHERE Id IN :contactIds]
        );

        // Validation: check each request
        for (SoftCreditRequest request : requests) {
            Opportunity opp = oppMap.get(request.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + request.opportunityId);
            }

            // Check if contact is primary contact
            if (request.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('Contact is the primary contact for opportunity: ' + request.opportunityId);
            }

            // Check amount validity
            if (request.amount == null || request.amount <= 0 || request.amount > opp.Amount) {
                throw new SoftCreditException('Amount invalid for opportunity: ' + request.opportunityId);
            }
        }

        // Prepare OCRs to save
        List<OpportunityContactRole> ocrsToSave = new List<OpportunityContactRole>();
        for (SoftCreditRequest request : requests) {
            Id oppId = request.opportunityId;
            Id contactId = request.contactId;
            String role = request.role;

            String key = oppId + '-' + contactId;
            OpportunityContactRole ocr = ocrMap.get(key);

            if (ocr == null) {
                // Create new OCR
                ocr = new OpportunityContactRole(
                    OpportunityId = oppId,
                    ContactId = contactId,
                    Role = role
                );
                ocrsToSave.add(ocr);
            } else if (ocr.Role != role) {
                // Update existing OCR role
                ocr.Role = role;
                ocrsToSave.add(ocr);
            }
        }

        // Save OCRs first
        if (!ocrsToSave.isEmpty()) {
            upsert ocrsToSave;
        }

        // Prepare PSCs to save
        List<npsp__Partial_Soft_Credit__c> pscsToSave = new List<npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest request : requests) {
            Id oppId = request.opportunityId;
            Id contactId = request.contactId;
            Decimal amount = request.amount;
            String role = request.role;

            String key = oppId + '-' + contactId;

            // Get the OCR (either existing or newly created)
            OpportunityContactRole ocr = ocrMap.get(key);
            if (ocr == null) {
                // Find the newly created OCR from ocrsToSave
                for (OpportunityContactRole newOcr : ocrsToSave) {
                    if (newOcr.OpportunityId == oppId && newOcr.ContactId == contactId) {
                        ocr = newOcr;
                        break;
                    }
                }
            }

            npsp__Partial_Soft_Credit__c psc = pscMap.get(key);
            if (psc == null) {
                // Create new PSC
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = oppId,
                    npsp__Contact__c = contactId,
                    npsp__Amount__c = amount,
                    npsp__Role_Name__c = role,
                    npsp__Contact_Role_ID__c = String.valueOf(ocr.Id)
                );
                pscsToSave.add(psc);
            } else {
                // Update existing PSC
                psc.npsp__Amount__c = amount;
                psc.npsp__Role_Name__c = role;
                psc.npsp__Contact_Role_ID__c = String.valueOf(ocr.Id);
                pscsToSave.add(psc);
            }
        }

        // Save PSCs
        if (!pscsToSave.isEmpty()) {
            upsert pscsToSave;
        }
    }
}
