public with sharing class RecordAccessService {
    public static Set<Id> editableIds(Set<Id> recordIds) {
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        Set<Id> editableIds = new Set<Id>();
        List<Id> idList = new List<Id>(recordIds);

        // Process in batches of 200 to respect UserRecordAccess query limit
        for (Integer i = 0; i < idList.size(); i += 200) {
            List<Id> batch = idList.subList(i, Math.min(i + 200, idList.size()));

            List<UserRecordAccess> accesses = [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE RecordId IN :batch
                  AND UserId = :UserInfo.getUserId()
            ];

            for (UserRecordAccess access : accesses) {
                if (access.HasEditAccess) {
                    editableIds.add(access.RecordId);
                }
            }
        }

        return editableIds;
    }
}
