public with sharing class DiscountApprovalService {
    @AuraEnabled
    public static Boolean canApprove(Decimal discountPercent) {
        if (discountPercent == null || discountPercent < 0) {
            return false;
        }
        if (discountPercent <= 15) {
            return true;
        }
        // For discounts above 15%, check if the running user has the custom permission
        return UserHasPermission('Approve_Large_Discount');
    }

    private static Boolean UserHasPermission(String permissionName) {
        Id userId = UserInfo.getUserId();

        // Query PermissionSetPermission to check if user has the custom permission
        List<PermissionSetPermission> permissions = [
            SELECT PermissionName
            FROM PermissionSetPermission
            WHERE PermissionSetId IN (
                SELECT PermissionSetId 
