public with sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    public void beforeInsert(List<SObject> triggerNew) {
        handleContacts(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldContacts = new Map<Id, Contact>((List<Contact>)triggerOld);
        handleContacts(triggerNew, oldContacts);
    }

    private void handleContacts(List<SObject> triggerNew, Map<Id, Contact> oldContacts) {
        // Identify contacts that need validation
        List<Contact> contactsToCheck = new List<Contact>();

        for (SObject sObj : triggerNew) {
            Contact c = (Contact)sObj;

            // Must have AccountId and Email to be checked
            if (c.AccountId != null && c.Email != null) {
                if (oldContacts == null) {
                    // Insert context - always check
                    contactsToCheck.add(c);
                } else {
                    // Update context - only check if Email or AccountId changed
                    Contact oldC = oldContacts.get(c.Id);
                    if (c.Email != oldC.Email || c.AccountId != oldC.AccountId) {
                        contactsToCheck.add(c);
                    }
                }
            }
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        // Get all account IDs involved
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contactsToCheck) {
            accountIds.add(c.AccountId);
        }

        // Single SOQL query to get existing contacts for these accounts
        List<Contact> existingContacts = [
            SELECT Id, AccountId, Email 
            FROM Contact 
            WHERE AccountId IN :accountIds 
            AND Email != null
        ];

        // Build map of AccountId -> lowercase Email -> Contact (first one encountered)
        Map<Id, Map<String, Contact>> accountEmailMap = new Map<Id, Map<String, Contact>>();

        for (Contact c : existingContacts) {
            Id accountId = c.AccountId;
            String emailLower = c.Email.toLowerCase();

            if (!accountEmailMap.containsKey(accountId)) {
                accountEmailMap.put(accountId, new Map<String, Contact>());
            }

            // Only store the first contact with this email for each account
            if (!accountEmailMap.get(accountId).containsKey(emailLower)) {
                accountEmailMap.get(accountId).put(emailLower, c);
            }
        }

        // Track contacts accepted in this trigger execution
        Map<Id, Contact> acceptedContactsInTrigger = new Map<Id, Contact>();

        // Process contacts in order (first in list is accepted, later ones rejected)
        for (Contact c : contactsToCheck) {
            Id accountId = c.AccountId;
            String emailLower = c.Email.toLowerCase();

            Boolean hasDuplicate = false;

            // Check against existing contacts in DB
            Map<String, Contact> emailMapForAccount = accountEmailMap.get(accountId);
            if (emailMapForAccount != null && emailMapForAccount.containsKey(emailLower)) {
                Contact existing = emailMapForAccount.get(emailLower);
                // Contact doesn't conflict with itself
                if (existing.Id != c.Id) {
                    hasDuplicate = true;
                }
            }

            // Check against other contacts in this trigger execution that were already accepted
            if (!hasDuplicate) {
                for (Contact accepted : acceptedContactsInTrigger.values()) {
                    if (accepted.AccountId == c.AccountId && accepted.Email.toLowerCase() == emailLower) {
                        hasDuplicate = true;
                        break;
                    }
                }
            }

            if (hasDuplicate) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                // This contact is accepted - add to tracked accepted contacts
                acceptedContactsInTrigger.put(c.Id, c);

                // Also add to the accountEmailMap so subsequent contacts in this save see it
                if (!accountEmailMap.containsKey(accountId)) {
                    accountEmailMap.put(accountId, new Map<String, Contact>());
                }
                accountEmailMap.get(accountId).put(emailLower, c);
            }
        }
    }
}
